        'kullanim-kosullari' => array(
            'title' => 'Kullanım Koşulları',
            'icon'  => '📜',
            'intro' => '724PazarYeri üyelik ve mesafeli satış sözleşmesini kapsayan kullanım koşulları aşağıda yer almaktadır. Platformu kullanarak bu koşulları kabul etmiş sayılırsınız.',
            'sections' => array(
                array('Satıcı', 'Adı/Unvanı: Fahrettin POLAT Adresi:ADALET MAH. MANAS BLV. FOLKART TOWERS NO: 39 İÇ KAPI NO: 3408 BAYRAKLI/ İZMİR Telefon: 0530 788 75 40 E-posta:destek@724pazaryeri.com Site: https://724pazaryeri.com/'),
                array('Alıcı', 'Adı Soyadı:[fatura-isim] Şirket:[fatura-firma] TC Kimlik No:[tc-kimlik-no] Vergi Dairesi:[vergi-dairesi] Vergi Numarası:[vergi-numarasi] Fatura Adresi:[fatura-adres]'),
                array('Madde 2 – Sözleşmenin Konusu', 'İş bu sözleşmenin konusu, Alıcının Satıcıya ait 724pazaryeri.com web sitesinden elektronik ortamda sipariş verdiği, sözleşmede bahsi geçen nitelikleri haiz ve yine sözleşmede satış fiyatı belirtilen mal/hizmetin satışı ve teslimi ile ilgili olarak 4077 sayılı Tüketicilerin Korunması Hakkındaki Kanun ve Mesafeli Sözleşmeler Uygulama Esas ve Usulleri Hakkında Yönetmelik hükümleri gereğince tarafların hak ve yükümlülüklerinin saptanmasıdır. Alıcı, satışa konu mal/hizmetlerin temel nitelikleri, satış fiyatı, ödeme şekli, teslimat koşulları vs. satışa konu mal/hizmet ile ilgili tüm ön bilgiler ve “cayma” hakkı konusunda bilgi sahibi olduğunu, bu ön bilgileri elektronik ortamda teyit ettiğini ve sonrasında mal/hizmeti sipariş verdiğini is bu sözleşme hükümlerince kabul ve beyan eder. 724pazaryeri.com sitesinde ödeme sayfasında yer alan ön bilgilendirme ve fatura iş bu sözleşmenin ayrılmaz parçalarıdır.'),
                array('Madde 3 – Sözleşme Tarihi', 'Satıcı tarafından daha önce imzalanmış bulunan iş bu iki nüsha sözleşme alıcı tarafından[tarih]tarihinde verilen sipariş ile kabul edilmiş sayılır.'),
                array('Madde 4 – Mal/hizmetin Teslimi, Sözleşmenin İfa Yeri ve Teslim Şekli', 'Mal/hizmet, alıcının teslimini talep etmiş olduğu[kargo-adres]adresinde[fatura-isim]adına teslim edilecektir.'),
                array('Madde 5 – Teslimat Masrafları ve İfası', 'Teslimat masrafları alıcıya aittir. Satıcı, web sitesinde, ilan ettiği rakamın üzerinde alışveriş yapanların teslimat ücretinin kendisince karşılanacağını ya da kampanya dahilinde ücretsiz teslimat yapacağını beyan etmişse, teslimat masrafı satıcıya aittir. Teslimat; stokun müsait olması ve mal bedelinin satıcının hesabına geçmesinden sonra en kısa sürede yapılır. Satıcı, mal/hizmetin siparişinden itibaren 30 (Otuz) gün içinde teslim eder ve bu süre içinde yazılı bildirimle ek 10 (on) günlük süre uzatım hakkını saklı tutar. Herhangi bir nedenle mal/hizmet bedeli ödenmez veya banka kayıtlarında iptal edilir ise, satıcı mal/hizmetin teslimi yükümlülüğünden kurtulmuş kabul edilir.'),
                array('Madde 6 – Alıcının Beyan ve Taahhütleri', 'Alıcı, sözleşme konusu mal/hizmeti teslim almadan önce muayene edecek; ezik, kırık, ambalajı yırtılmış vb. hasarlı ve ayıplı mal/hizmeti kargo şirketinden teslim almayacaktır. Teslim alınan mal/hizmetin hasarsız ve sağlam olduğu kabul edilecektir. Teslimden sonra mal/hizmetin özenle korunması borcu, alıcıya aittir. Cayma hakkı kullanılacaksa mal/hizmet kullanılmamalıdır. Fatura iade edilmelidir. Mal/hizmetin tesliminden sonra alıcıya ait kredi kartının alıcının kusurundan kaynaklanmayan bir şekilde yetkisiz kişilerce haksız veya hukuka aykırı olarak kullanılması nedeni ile ilgili banka veya finans kuruluşunun mal/hizmet bedelini satıcıya ödememesi halinde, Alıcı kendisine teslim edilmiş olması kaydıyla mal/hizmeti 3 (Üç) gün içinde satıcıya göndermekle yükümlüdür. Bu takdirde teslimat giderleri alıcıya aittir.'),
                array('Madde 7 – Satıcının Beyan ve Taahhütleri', 'Satıcı, sözleşme konusu mal/hizmetin sağlam, eksiksiz, siparişte belirtilen niteliklere uygun ve varsa garanti belgeleri ve kullanım kılavuzları ile teslim edilmesinden sorumludur. Sözleşme konusu mal/hizmet, alıcıdan başka bir kişi/kuruluşa teslim edilecek ise, teslim edilecek kişi/kuruluşun teslimatı kabul etmemesinden satıcı sorumlu tutulamaz. Satıcı, cayma beyanının kendisine ulaşmasından sonra 10 (on) gün içinde mal/hizmet bedelini, varsa kıymetli evrakı iade eder. Mal/hizmeti 14 (ondört) gün içinde iade alır. Haklı gerekçelerle satıcı, sözleşmedeki ifa süresi dolmadan alıcıya eşit kalite ve fiyatta tedarik edebilir. Satıcı mal/hizmetin ifasının imkânsızlaştığını düşünüyorsa, sözleşmenin ifa süresi dolmadan alıcıya bildirir. Ödenen bedel ve varsa belgeler 7 (yedi) gün içinde iade edilir. Garanti belgesi ile satılan mal/hizmetlerden olan veya olmayan mal/hizmetlerden arızalı veya bozuk olan mal/hizmetler, garanti şartları içinde gerekli onarımın yapılması için satıcıya gönderilebilir, bu takdirde teslimat giderleri satıcı tarafından karşılanacaktır.'),
                array('Madde 8 – Sözleşmeye Konu Mal/hizmetin Özellikleri', 'Mal/hizmetin cinsi ve türü, miktarı, marka/modeli, rengi ve tüm vergiler dâhil satış bedeli 724PazarYeri.com adlı web sitesindeki mal/hizmet tanıtım sayfasında yer alan bilgilerde ve iş bu sözleşmenin ayrılmaz parçası sayılan faturada belirtildiği gibidir. Sipariş edilen ürünler: [urun-listesi] Ara Toplam:[sepet-tutar] Kargo Ücreti:[kargo-tutar] Vergi Tutarı:[vergi-tutar] Sipariş Toplamı:[toplam-tutar]'),
                array('Madde 9 – Mal/hizmetin Peşin Fiyatı', 'Mal/hizmetin peşin fiyatı, bu sözleşmenin 8. Maddesinde ve sipariş özetinde belirtilen toplam tutardır.'),
                array('Madde 10 – Vadeli Fiyat', 'Mal/hizmetin satış fiyatına yapılan vadeye göre fiyatı, bu sözleşmenin 8. Maddesinde ve sipariş özetinde belirtilen toplam tutardır.'),
                array('Madde 11 – Faiz', 'Her yıl Türkiye Cumhuriyeti Hükümetinin belirlediği faiz oranından ve her halde %30dan fazla olamaz. Alıcı çalıştığı bankaya karşı sorumludur.'),
                array('Madde 12 – Peşinat Tutarı', 'Mal/hizmetin peşinat tutarı, bu sözleşmenin 8. Maddesinde ve sipariş özetinde belirtilen toplam tutardır.'),
                array('Madde 13 – Ödeme Planı', 'Ödeme yöntemi[odeme-yontemi]olarak seçilmiştir. Alıcının, kredi kartı ile ve taksitle alışveriş yapması durumunda siteden seçmiş olduğu taksit biçimi geçerlidir. Taksitlendirme işlemlerinde, alıcı ile kart sahibi banka arasında imzalamış bulunan sözleşmenin ilgili hükümleri geçerlidir. Kredi kartı ödeme tarihi banka ile alıcı arasındaki sözleşme hükümlerince belirlenir. Alıcı, ayrıca bankanın gönderdiği hesap özetinden taksit sayısını ve ödemelerini takip edebilir.'),
                array('Madde 14 – Cayma Hakkı', 'Alıcı, sözleşme konusu mal/hizmetin kendisine veya gösterdiği adresteki kişi/kuruluşa tesliminden itibaren 7 (yedi) gün içinde cayma hakkını kullanabilir. Cayma hakkının kullanılması için aynı süre içinde satıcının müşteri hizmetlerine e-posta veya telefon ile bildirimde bulunulması ve mal/hizmetin 15. madde hükümleri çerçevesinde ve iş bu sözleşmenin ayrılmaz parçası olan ve 724pazaryeri.com web sitesinde yayınlanmış olan ön bilgiler gereğince, kullanılmamış olması şarttır. Bu hakkın kullanılması halinde, 3. kişiye veya alıcıya teslim edilen mal/hizmete ilişkin fatura aslının iadesi zorunludur. Cayma hakkına ilişkin ihbarın ulaşmasını takip eden 7 gün içinde mal/hizmet bedeli alıcıya iade edilir ve 14 (ondört) günlük süre içinde mal/hizmet iade alınır. Fatura aslı gönderilmezse alıcıya KDV ve varsa diğer yasal yükümlülükler iade edilemez. Cayma hakkı nedeni ile iade edilen mal/hizmetin teslimat bedeli satıcı tarafından karşılanır.'),
                array('Madde 15 – Cayma Hakkı Kullanılamayacak Mal/hizmetler', 'Niteliği itibarıyla iade edilemeyecek mal/hizmetler, hızla bozulan ve son kullanma tarihi geçen mal/hizmetler, tek kullanımlık mal/hizmetler, hijyenik mal/hizmetler, kopyalanabilir her türlü yazılım ve programlardır. Ayrıca, her türlü yazılım ve programlarında, Çeşitli mediaların (Dvd,Cd v.b), bilgisayar ve kırtasiye sarf malzemelerinde (toner, kartuş, şerit v.b) ile kozmetik malzemelerinde cayma hakkının kullanılabilmesi için mal/hizmetin ambalajının açılmamış, bozulmamış ve kullanılmamış olmaları şartı bulunmaktadır.'),
                array('Madde 16 – Temerrüd Hali ve Hukuki Sonuçları', 'Alıcı, kredi kartı ile yapmış olduğu işlemlerinde temerrüde düşmesi halinde kart sahibi bankanın kendisi ile yapmış olduğu kredi kartı sözleşmesi çerçevesinde faiz ödeyecek ve bankaya karşı sorumlu olacaktır. Bu durumda ilgili banka hukuki yollara başvurabilir; doğacak masrafları ve vekalet ücretini alıcıdan talep edebilir ve her koşulda alıcının borcundan dolayı temerrüde düşmesi halinde, alıcı, borcun gecikmeli ifasından dolayı satıcının oluşan zarar ve ziyanını ödemeyi kabul eder.'),
                array('Madde 17 – İptal ve İade', 'Aldığım ürün ne zaman teslim edilir? Normal şartlar altında, Teslimatlar kargoya verildikten sonra (kargo firmasının bulunduğunuz il ve ilçeye taahhüt ettiği teslim süresine göre değişmekle birlikte) 2-3 gün içinde yapılır. Eğer ürün tedarik sürecinde herhangi bir sorun yaşanırsa, müşteri hizmetleri temsilcilerimiz e-posta yoluyla sizi bu durum hakkında bilgilendirir. Adresime yakın kargo şirketi yok, siparişimi nasıl teslim alacağım? Anlaşmalı olduğumuz kargo firmaları genelde Türkiyenin her yerine ürün teslimi yapmaktadır. Eğer bulunduğunuz yerde kargo acentesi yoksa, orası “mobil bölge” kapsamında değerlendirilir ve haftanın belli günlerinde ürün teslimi yapılır. Sitemizde belirtilen ürün tedarik süreci ve kargo ücretleri il, ilçe merkezleri için geçerlidir. İl, ilçe merkezleri ve mobil bölgenin dışında kalan noktalara ürün teslimi yapılamaz; yapılsa da ekstra bir kargo ücreti talep edilir. “Tedarik Sürecinde” uyarısı ne anlama gelir? Sipariş verdiğiniz ürün stoklarımızda varsa kargolama işlemlerine hemen başlanır. Siparişinizde birden çok ürün olması durumunda, ilk sipariş verilen üründen başlayarak, stoklarımızda olanların hazırlanmasına başlanır Stoklarımızda henüz bulunmayan siparişleriniz için ise tedarik süreci başlar. (Bu durumda, sipariş ettiğiniz ürünün karşısında “Tedarik Sürecinde” yazısını görürsünüz.) İlgili tedarikçimize otomatik olarak geçilen talepler takip edilir ve siparişlerinizin en kısa sürede stoklarımızda yer alması sağlanır. Siparişimin kargoya verildiğini nasıl anlayacağım? Sitemizden aldığınız ürünler kargoya teslim edildiğinde, sistemimizde kayıtlı e-posta adresinize ve cep telefonunuza SMS olarak siparişinizle ilgili kargo gönderi bilgileri otomatik olarak gönderilir. Bu bilgilendirme yardımıyla ürün ya da ürünlerinizin kargoya ne zaman teslim edildiğini öğrenebilirsiniz. Ayrıca “Hesabım” sayfasındaki “Siparişlerim” bölümünden siparişinizin durumunu takip edebilirsiniz. Teslimat sırasında nelere dikkat etmeliyim? Siparişleriniz adresinize teslim edildiğinde, kargo teslim fişini imzaladıktan sonra kargo paketini açıp kontrol etmenizi öneririz. Paket içeriğinde herhangi bir yanlışlık varsa ya da ürünler hasar görmüş, deforme olmuşsa lütfen kargo görevlisine “Hasar Tespit Tutanağı” hazırlatıp bu konuda bizimle iletişime geçin. Kargom yanlış adrese gidiyor, ne yapabilirim? Siparişiniz kargoya verildiğinde teslimat adresiniz hiçbir değişiklik yapılmadan otomatik olarak kargo firmasının sistemine aktarılır ve gönderi işlemi bu doğrultuda devam eder. Teslimat şubeleri, kargo firması tarafından adresinize bağlı bulunan şubeye çıkarılır. Dolayısıyla ürünün teslimat için hangi şubeye verileceği bize bağlı bir seçim değildir. Kargonuz eğer yanlış adrese ya da şubeye gönderilmişse, bize “Müşteri Hizmetleri” sayfasından mesaj yoluyla bilgi verdiğiniz takdirde kargo firması tarafımızca bilgilendirilir ve yönlendirme işlemleri en kısa sürede yapılır. Kargo teslimat adresinde beni bulamazsa ne olur? Birlikte çalıştığımız kargo firmaları eğer teslimat adresinde kimseye ulaşamazsa kapıya bir pusula bırakır. Bu pusula üzerinde size teslimat yapan kargo şubesinin adres ve telefonları bulunur. Kargo şubesi kolinizi 3 gün boyunca bekletir ve size ulaşamadığı takdirde siparişinizi geri gönderir. Adresinizde bulunmadığınız için kargonuzu teslim alamadığınızda, kargo şubenize pusuladaki bilgiler doğrultusunda ulaşabilir ve teslimatla ilgili ayrıntılı bilgi alabilirsiniz. Teslimat adresimi değiştirebilir miyim? Teslimat adresi değişikliğini, siparişinizin tamamı tedarik sürecindeyken bize “Müşteri Hizmetleri” sayfasından mesajla bildirebilirsiniz. Ancak siparişinizdeki bir ya da birkaç ürün daha önceden kargoya verildiyse (kısmi teslimat), önceden belirlediğiniz teslimat adresi kargo firmasına online olarak aktarıldığı ve tek sipariş için yapılan her kargo çıkışında aynı teslimat adresi kullanıldığı için sistem üzerinden yapılacak adres değişikliği kargo firmasının sistemine hemen yansımaz. Siparişim hasarlı, kırık geldi. Ne yapmalıyım? Satışa sunduğumuz tüm ürünler, tedarikçi firmadan alınırken ve kargoya teslim edilmek üzere paketlenirken hasar kontrolünden geçer. Dolayısıyla, hiçbir ürünün hasarlı olarak gönderilme olasılığı yoktur. Buna rağmen cam eşya, elektrikli ısıtıcı gibi niteliği itibarıyla hassas ürünlerde, taşıma sırasında düşürülmesi veya kargoya hatalı yüklenmesi nedeniyle hasar oluşabilir. Böyle bir durumda süreç şöyle işler: Siparişiniz kargo görevlisi tarafından adresinize ulaştırıldığında, ürünü teslim almadan önce mutlaka dış pakette hasar kontrolü yapın ve herhangi bir hasar gördüğünüz anda “Hasar Tespit Tutanağı” hazırlatın. Hasar Tespit Tutanağı hazırlanırken kargo görevlisinin tutanağa yazdığı açıklamalara dikkat edin. Örneğin; “Kolide hasar bulunmamaktadır. Ürün hasarlıdır.” gibi bir açıklama, ürünün taşınma sırasında zarar görmediği şeklinde yorumlanır ve değişim talebiniz sırasında sorun yaşamanıza neden olur. Hasarlı gelen ürünle ilgili tam ve doğru kelimelerle tutanak tutması için görevliyi uyarın. “Ürün teslim edildiğinde kontrol edildi ve hasarlı olduğu görüldü.” gibi bir açıklamanın yer aldığı tutanak, ürün iade işleminizi hızlandıracaktır. Sipariş tesliminden sonra fark ettiğiniz bir hasar durumunda, ilgili kargo şubesiyle hemen iletişim kurmanız ve “Hasar Tespit Tutanağı” hazırlamalarını istemeniz gerekir. Eğer kargo şubesi size bu konuda yardımcı olmuyorsa, lütfen en kısa sürede bizi bilgilendirin. Bize ürünü göndermeden önce “Hesabım” sayfasındaki sipariş detayında yer alan Arıza/İade/Değişim butonuna tıklayarak başvuruda bulunmalısınız Hasar Tespit Tutanağıyla birlikte hasarlı ürünü bize gönderdiğinizde ürün değişimi işlemleriniz hızla tamamlanır ve size bu konuda bilgi verilir. Kargo tazmini konusunda sorun yaşamamak için, hasarlı ürünü size teslimatı yapan kargo firmasıyla geri gönderin. Aldığım ürünün paket içeriği eksik çıktı, ne yapmalıyım? Satışa sunulan ürünler, tedarikçi firmalardan orijinal kutularında gelir ve hiç açılmadan paketleme yapılarak kargoya teslim edilir. Ürünlerin sevkiyatında yaşanabilecek olası sorunlara karşı kargo paketleri üzerine yapıştırdığımız etiketlerde bir uyarı yazısı göreceksiniz. Bu uyarıda, teslimat sırasında kargo görevlisi yanınızdayken ürünü açıp kontrol etmeniz gerektiği hatırlatılmaktadır. Yapacağınız kontrol sonucunda ürün paket içeriğinde bir eksik ya da hata olduğu takdirde, kargo görevlisine “Durum Tespit Tutanağı” hazırlatmanız gerekir. Bu işlemin ardından dilerseniz ürünü teslim alabilir, sadece tutanakla birlikte bize başvuruda bulunabilirsiniz. Paket içeriğindeki eksik ya da hatalı olduğunu teslimat sonrasında fark ederseniz, tutanak olmadan da bize başvurabilirsiniz. Sipariş Detayı sayfasından “Arıza/İade/Değişim” bölümünden konuyla ilgili formu doldurmanız yeterli olacaktır. Siparişimdeki ürünle bana gelen ürün farklı, ne yapmalıyım? Stok kodlamasında yaşanan bir hata nedeniyle farklı bir ürün gönderilmişse öncelikle sizden özür dileriz. Değişim işleminin yapılabilmesi için söz konusu ürünü lütfen kargodan çıkan iade değişim formunu doldurarak bize geri gönderin. Ürün elimize ulaştığında gerekli işlemler yapılacaktır.'),
                array('Madde 18 – Yetkili Mahkeme', 'İş bu sözleşmeden kaynaklanabilecek ihtilaflarda, Sanayi ve Ticaret Bakanlığınca ilan edilen değere kadar Tüketici Hakem Heyetleri, belirtilen değer üstüne Tüketici Mahkemeleri; bulunamayan yerlerde Asliye Hukuk Mahkemeleri yetkilidir.'),
                array('Birinci Bölüm', 'Amaç, Kapsam, Dayanak ve Tanımlar Amaç'),
                array('Madde 1 (1) Bu Yönetmeliğin amacı, mesafeli sözleşmelere ilişkin uygulama usul ve esaslarını düzenlemektir.', 'Kapsam'),
                array('Madde 2 (1) Bu Yönetmelik, mesafeli sözleşmelere uygulanır.', '(2) Bu Yönetmelik hükümleri; 1. a) Finansal hizmetler, 2. b) Otomatik makineler aracılığıyla yapılan satışlar, 3. c) Halka açık telefon vasıtasıyla telekomünikasyon operatörleriyle bu telefonun kullanımı, ç) Bahis, çekiliş, piyango ve benzeri şans oyunlarına ilişkin hizmetler, 4. d) Taşınmaz malların veya bu mallara ilişkin hakların oluşumu, devri veya kazanımı, 5. e) Konut kiralama, 6. f) Paket turlar, 7. g) Devre mülk, devre tatil, uzun süreli tatil hizmeti ve bunların yeniden satımı veya değişimi, ğ) Yiyecek ve içecekler gibi günlük tüketim maddelerinin, satıcının düzenli teslimatları çerçevesinde tüketicinin meskenine veya işyerine götürülmesi, 8. h) 5 inci maddenin birinci fıkrasının (a), (b) ve (d) bentlerindeki bilgi verme yükümlülüğü ile 18 inci ve 19 uncu maddelerde yer alan yükümlülükler saklı kalmak koşuluyla yolcu taşıma hizmetleri, ı) Malların montaj, bakım ve onarımı, 9. i) Bakımevi hizmetleri, çocuk, yaşlı ya da hasta bakımı gibi ailelerin ve kişilerin desteklenmesine yönelik sosyal hizmetler 10. j)(Ek:RG-23/8/2022-31932)(1)Kısa mesaj aracılığıyla kurulan ve eş zamanlı olarak tamamen ifa edilen abonelik içermeyen katma değerli elektronik haberleşme hizmetleri ile 23/6/1983 tarihli ve 2860 sayılı Yardım Toplama Kanunu kapsamındaki bağışlar ve kamu kurumlarınca sunulan katma değerli elektronik haberleşme hizmetleri, ile ilgili sözleşmelere uygulanmaz. Dayanak'),
                array('Madde 3 (1) Bu Yönetmelik, 7/11/2013 tarihli ve 6502 sayılı Tüketicinin Korunması Hakkında Kanunun 48 inci ve 84 üncü maddelerine dayanılarak hazırlanmıştır.', 'Tanımlar'),
                array('Madde 4 (1) Bu Yönetmeliğin uygulanmasında;', '11. a) Dijital içerik: Bilgisayar programı, uygulama, oyun, müzik, video ve metin gibi dijital şekilde sunulan her türlü veriyi, 12. b) Hizmet: Bir ücret veya menfaat karşılığında yapılan ya da yapılması taahhüt edilen mal sağlama dışındaki her türlü tüketici işleminin konusunu, 13. c) Kalıcı veri saklayıcısı: Tüketicinin gönderdiği veya kendisine gönderilen bilgiyi, bu bilginin amacına uygun olarak makul bir süre incelemesine elverecek şekilde kaydedilmesini ve değiştirilmeden kopyalanmasını sağlayan ve bu bilgiye aynen ulaşılmasına imkan veren kısa mesaj, elektronik posta, internet, disk, CD, DVD, hafıza kartı ve benzeri her türlü araç veya ortamı, ç) Kanun: 6502 sayılı Tüketicinin Korunması Hakkında Kanunu, 14. d) Mal: Alışverişe konu olan; taşınır eşya, konut veya tatil amaçlı taşınmaz mallar ile elektronik ortamda kullanılmak üzere hazırlanan yazılım, ses, görüntü ve benzeri her türlü gayri maddi malları, 15. e) Mesafeli sözleşme: Satıcı veya sağlayıcı ile tüketicinin eş zamanlı fiziksel varlığı olmaksızın, mal veya hizmetlerin uzaktan pazarlanmasına yönelik olarak oluşturulmuş bir sistem çerçevesinde, taraflar arasında sözleşmenin kurulduğu ana kadar ve kurulduğu an da dahil olmak üzere uzaktan iletişim araçlarının kullanılması suretiyle kurulan sözleşmeleri, 16. f) Sağlayıcı: Kamu tüzel kişileri de dahil olmak üzere ticari veya mesleki amaçlarla tüketiciye hizmet sunan ya da hizmet sunanın adına ya da hesabına hareket eden gerçek veya tüzel kişiyi, 17. g) Satıcı: Kamu tüzel kişileri de dahil olmak üzere ticari veya mesleki amaçlarla tüketiciye mal sunan ya da mal sunanın adına ya da hesabına hareket eden gerçek veya tüzel kişiyi, ğ) Tüketici: Ticari veya mesleki olmayan amaçlarla hareket eden gerçek veya tüzel kişiyi, 18. h) Uzaktan iletişim aracı: Mektup, katalog, telefon, faks, radyo, televizyon, elektronik posta mesajı, kısa mesaj, internet gibi fiziksel olarak karşı karşıya gelinmeksizin sözleşme kurulmasına imkan veren her türlü araç veya ortamı, ı) Yan sözleşme: Bir mesafeli sözleşme ile ilişkili olarak satıcı, sağlayıcı(Ek ibare:RG-23/8/2022-31932)(1), aracı hizmet sağlayıcı ya da üçüncü bir kişi tarafından sözleşme konusu mal ya da hizmete ilave olarak tüketiciye sağlanan mal veya hizmete ilişkin sözleşmeyi 19. i)(Ek:RG-23/8/2022-31932)(1)Aracı hizmet sağlayıcı: Oluşturduğu sistem ile uzaktan iletişim araçlarını kullanmak veya kullandırmak suretiyle satıcı veya sağlayıcı adına mesafeli sözleşme kurulmasına aracılık eden gerçek veya tüzel kişiyi, 20. j)(Ek:RG-23/8/2022-31932)(1)Platform: Kamu hizmetlerinin tek noktadan sunulduğu ortak kamu elektronik platformu hariç olmak üzere, aracı hizmet sağlayıcının mesafeli sözleşme kurulmasına aracılık etmek üzere oluşturduğu sistemi, ifade eder.'),
                array('İkinci Bölüm', 'Ön Bilgilendirme Yükümlülüğü Ön bilgilendirme'),
                array('Madde 5 (1) Tüketici, mesafeli sözleşmenin kurulmasından ya da buna karşılık gelen herhangi bir teklifi kabul etmeden önce, aşağıdaki hususların tamamını içerecek şekilde satıcı veya sağlayıcı tarafından bilgilendirilmek zorundadır.', '21. a) Sözleşme konusu mal veya hizmetin temel nitelikleri, 22. b)(Değişik:RG-23/8/2022-31932)(1)Satıcı veya sağlayıcı ile aracı hizmet sağlayıcının adı veya unvanı, MERSİS numarası veya vergi kimlik numarası, 23. c)(Değişik:RG-23/8/2022-31932)(1)Tüketicinin satıcı veya sağlayıcı ve aracı hizmet sağlayıcı ile hızlı bir şekilde irtibat kurmasına imkan veren açık adres, telefon numarası ve benzeri iletişim bilgileri ile varsa satıcı veya sağlayıcının adına ya da hesabına hareket edenin kimliği ve adresi, ç)(Değişik:RG-23/8/2022-31932)(1)Satıcı veya sağlayıcı ile aracı hizmet sağlayıcının tüketicinin şikayetlerini iletmesi için (c) bendinde belirtilenden farklı iletişim bilgileri var ise, bunlara ilişkin bilgi, 24. d) Mal veya hizmetin tüm vergiler dahil toplam fiyatı, niteliği itibariyle önceden hesaplanamıyorsa fiyatın hesaplanma usulü, varsa tüm nakliye, teslim ve benzeri ek masraflar ile bunların önceden hesaplanamaması halinde ek masrafların ödenebileceği bilgisi, 25. e) Sözleşmenin kurulması aşamasında uzaktan iletişim aracının kullanım bedelinin olağan ücret tarifesi üzerinden hesaplanamadığı durumlarda, tüketicilere yüklenen ilave maliyet, 26. f)(Değişik:RG-23/8/2022-31932)(1)Ödeme, ticari reklam ve tanıtımlarında taahhüt edilen süre ile uyumlu teslim veya ifa süresi, teslimat ve ifaya ilişkin diğer bilgiler ile varsa bunlara ilişkin taahhütler ve satıcı veya sağlayıcı ile aracı hizmet sağlayıcının şikayetlere ilişkin çözüm yöntemleri, 27. g)(Değişik:RG-24/5/2025-32909)(4)Cayma hakkının olduğu durumlarda, bu hakkın kullanılma şartları, süresi, usulü ve satıcının iade için öngördüğü taşıyıcıya ilişkin bilgiler, ğ) Cayma bildiriminin yapılacağı açık adres, faks numarası veya elektronik posta bilgileri, 28. h) 15 inci madde uyarınca cayma hakkının kullanılamadığı durumlarda, tüketicinin cayma hakkından faydalanamayacağına ya da hangi koşullarda cayma hakkını kaybedeceğine ilişkin bilgi, ı) Satıcı veya sağlayıcının talebi üzerine, varsa tüketici tarafından ödenmesi veya sağlanması gereken depozitolar ya da diğer mali teminatlar ve bunlara ilişkin şartlar, 29. i) Varsa dijital içeriklerin işlevselliğini etkileyebilecek teknik koruma önlemleri, 30. j) Satıcı veya sağlayıcının bildiği ya da makul olarak bilmesinin beklendiği, dijital içeriğin hangi donanım ya da yazılımla birlikte çalışabileceğine ilişkin bilgi, 31. k)(Değişik:RG-24/5/2025-32909)(4)Tüketicilerin uyuşmazlık konusundaki başvurularını tüketici hakem heyetine veya Kanunun 73/A maddesi uyarınca dava açılmadan önce arabulucuya başvurulması şartı ile tüketici mahkemesine yapabileceklerine ilişkin bilgi. (2) Birinci fıkrada belirtilen bilgiler, mesafeli sözleşmenin ayrılmaz bir parçasıdır ve taraflar aksini açıkça kararlaştırmadıkça bu bilgiler değiştirilemez. (3) Satıcı veya sağlayıcı, birinci fıkranın (d) bendinde yer alan ek masraflara ilişkin bilgilendirme yükümlülüğünü yerine getirmezse, tüketici bunları karşılamakla yükümlü değildir. (4) Birinci fıkranın (d) bendinde yer alan toplam fiyatın, belirsiz süreli sözleşmelerde veya belirli süreli abonelik sözleşmelerinde, her faturalama dönemi bazında toplam masrafları içermesi zorunludur. (5) Açık artırma veya eksiltme yoluyla kurulan sözleşmelerde, birinci fıkranın (b), (c) ve (ç) bentlerinde yer alan bilgilerin yerine açık artırmayı yapan ile ilgili bilgilere yer verilebilir. (6) Ön bilgilendirme yapıldığına ilişkin ispat yükü satıcı veya(Değişik ibare:RG-23/8/2022-31932)(1)sağlayıcı ile aracı hizmet sağlayıcıyaaittir. (7)(Ek:RG-23/8/2022-31932)(1)Mesafeli sözleşmenin platform üzerinden kurulması halinde aracı hizmet sağlayıcı ön bilgilendirmenin yapılmasından satıcı veya sağlayıcı ile birlikte müteselsilen sorumludur. Veri girişinin aracı hizmet sağlayıcı tarafından yapıldığı durumlarda, birinci fıkrada belirlenen zorunlu hususlardaki eksikliklerden ve verilerin doğruluğundan aracı hizmet sağlayıcı sorumludur. Ön bilgilendirme yöntemi'),
                array('Madde 6 (1) Tüketici, 5 inci maddenin birinci fıkrasında belirtilen tüm hususlarda, kullanılan uzaktan iletişim aracına uygun olarak en az on iki punto büyüklüğünde, anlaşılabilir bir dilde, açık, sade ve okunabilir bir şekilde satıcı veya sağlayıcı tarafından yazılı olarak veya kalıcı veri saklayıcısı ile bilgilendirilmek zorundadır.', '(2) Mesafeli sözleşmenin internet yoluyla kurulması halinde, satıcı veya sağlayıcı; 32. a) 5 inci maddenin birinci fıkrasında yer alan bilgilendirme yükümlülüğü saklı kalmak kaydıyla, aynı fıkranın (a), (d), (g) ve (h) bentlerinde yer alan bilgileri bir bütün olarak, tüketicinin ödeme yükümlülüğü altına girmesinden hemen önce açık bir şekilde ayrıca göstermek, 33. b) Herhangi bir gönderim kısıtlamasının uygulanıp uygulanmadığını ve hangi ödeme araçlarının kabul edildiğini, en geç tüketici siparişini vermeden önce, açık ve anlaşılabilir bir şekilde belirtmek zorundadır. (3) Mesafeli sözleşmenin sesli iletişim yoluyla kurulması halinde, satıcı veya sağlayıcı 5 inci maddenin birinci fıkrasının (a), (d), (g) ve (h) bentlerinde yer alan hususlarda, tüketiciyi sipariş vermeden hemen önce açık ve anlaşılır bir şekilde söz konusu ortamda bilgilendirmek ve 5 inci maddenin birinci fıkrasında yer alan bilgilerin tamamını en geç mal teslimine veya hizmet ifasına kadar yazılı olarak(Ek ibare:RG-23/8/2022-31932)(1) veya kalıcı veri saklayıcısı ilegöndermek zorundadır. (4) Siparişe ilişkin bilgilerin sınırlı alanda ya da zamanda sunulduğu bir ortam yoluyla mesafeli sözleşmenin kurulması halinde, satıcı veya sağlayıcı 5 inci maddenin birinci fıkrasının (a), (b), (d), (g) ve (h) bentlerinde yer alan hususlarda, tüketiciyi sipariş vermeden hemen önce açık ve anlaşılabilir bir şekilde söz konusu ortamda bilgilendirmek ve 5 inci maddenin birinci fıkrasında yer alan bilgilerin tamamını en geç mal teslimine veya hizmet ifasına kadar yazılı olarak(Ek ibare:RG-23/8/2022-31932)(1) veya kalıcı veri saklayıcısı ilegöndermek zorundadır. (5) Üçüncü ve dördüncü fıkralarda belirtilen yöntemlerle kurulan ve anında ifa edilen hizmet satışlarına ilişkin sözleşmelerde tüketicinin, sipariş vermeden hemen önce söz konusu ortamda 5 inci maddenin birinci fıkrasının sadece (a), (b), (d) ve (h) bentlerinde yer alan hususlarda açık ve anlaşılır bir şekilde bilgilendirilmesi yeterlidir. (6)(Ek:RG-23/8/2022-31932)(1)Mesafeli sözleşmenin platform üzerinden kurulması halinde aracı hizmet sağlayıcı bu maddede düzenlenen yükümlülüklerin yerine getirilmesinden satıcı veya sağlayıcı ile birlikte müteselsilen sorumludur. Veri girişinin satıcı veya sağlayıcı tarafından yapıldığı durumlar hariç olmak üzere, bu maddede belirtilen bilgilendirmelerde bulunulması zorunlu hususlardaki eksikliklerden ise aracı hizmet sağlayıcı sorumludur. Ön bilgilerin teyidi'),
                array('Madde 7 – (1) Satıcı Veya Sağlayıcı(ek İbare', 'RG-23/8/2022-31932)(1)ile aracı hizmet sağlayıcı, tüketicinin 6 ncı maddede belirtilen yöntemlerle ön bilgileri edindiğini kullanılan uzaktan iletişim aracına uygun olarak teyit etmesini sağlamak zorundadır. Aksi halde sözleşme kurulmamış sayılır. Ön bilgilendirmeye ilişkin diğer yükümlülükler'),
                array('Madde 8 – (1) Satıcı Veya Sağlayıcı(ek İbare', 'RG-23/8/2022-31932)(1)ile aracı hizmet sağlayıcı, tüketici siparişi onaylamadan hemen önce, verilen siparişin ödeme yükümlülüğü anlamına geldiği hususunda tüketiciyi açık ve anlaşılır bir şekilde bilgilendirmek zorundadır. Aksi halde tüketici siparişi ile bağlı değildir. (2) Tüketicinin mesafeli sözleşme kurulması amacıyla satıcı veya sağlayıcı tarafından telefonla aranması durumunda, her görüşmenin başında satıcı veya sağlayıcı kimliğini, eğer bir başkası adına veya hesabına arıyorsa bu kişinin kimliğini ve görüşmenin ticari amacını açıklamalıdır.'),
                array('Üçüncü Bölüm', 'Cayma Hakkının Kullanımı ve Tarafların Yükümlülükleri Cayma hakkı'),
                array('Madde 9 (1) Tüketici, on dört gün içinde herhangi bir gerekçe göstermeksizin ve cezai şart ödemeksizin sözleşmeden cayma hakkına sahiptir.', '(2) Cayma hakkı süresi, hizmet ifasına ilişkin sözleşmelerde sözleşmenin kurulduğu gün; mal teslimine ilişkin sözleşmelerde ise tüketicinin veya tüketici tarafından belirlenen üçüncü kişinin malı teslim aldığı gün başlar. Ancak tüketici, sözleşmenin kurulmasından malın teslimine kadar olan süre içinde de cayma hakkını kullanabilir. (3) Cayma hakkı süresinin belirlenmesinde; 34. a) Tek sipariş konusu olup ayrı ayrı teslim edilen mallarda, tüketicinin veya tüketici tarafından belirlenen üçüncü kişinin son malı teslim aldığı gün, 35. b) Birden fazla parçadan oluşan mallarda, tüketicinin veya tüketici tarafından belirlenen üçüncü kişinin son parçayı teslim aldığı gün, 36. c) Belirli bir süre boyunca malın düzenli tesliminin yapıldığı sözleşmelerde, tüketicinin veya tüketici tarafından belirlenen üçüncü kişinin ilk malı teslim aldığı gün esas alınır. (4) Malın satıcı tarafından taşıyıcıya teslimi, tüketiciye yapılan teslim olarak kabul edilmez. (5) Mal teslimi ile hizmet ifasının birlikte yapıldığı sözleşmelerde, mal teslimine ilişkin cayma hakkı hükümleri uygulanır. Eksik bilgilendirme'),
                array('Madde 10 – (1) Satıcı Veya Sağlayıcı(ek İbare', 'RG-23/8/2022-31932)(1)ile aracı hizmet sağlayıcı, cayma hakkı konusunda tüketicinin bilgilendirildiğini ispat etmekle yükümlüdür. Tüketici, cayma hakkı konusunda gerektiği şekilde bilgilendirilmezse, cayma hakkını kullanmak için on dört günlük süreyle bağlı değildir. Bu süre her halükarda cayma süresinin bittiği tarihten itibaren bir yıl sonra sona erer. (2) Cayma hakkı konusunda gerektiği şekilde bilgilendirmenin bir yıllık süre içinde yapılması halinde, on dört günlük cayma hakkı süresi, bu bilgilendirmenin gereği gibi yapıldığı günden itibaren işlemeye başlar. Cayma hakkının kullanımı'),
                array('Madde 11 – (1) Cayma Hakkının Kullanıldığına Dair Bildirimin Cayma Hakkı Süresi Dolmadan, Yazılı Olarak Veya Kalıcı Veri Saklayıcısı İle(değişik İbare', 'RG-23/8/2022-31932)(1)satıcı, sağlayıcı veya aracı hizmet sağlayıcıyayöneltilmesi yeterlidir. (2) Cayma hakkının kullanılmasında tüketici, EKte yer alan formu kullanabileceği gibi cayma kararını bildiren açık bir beyanda da bulunabilir. Satıcı veya sağlayıcı, tüketicinin bu formu doldurabilmesi veya cayma beyanını gönderebilmesi için internet sitesi üzerinden seçenek de sunabilir. İnternet sitesi üzerinden tüketicilere cayma hakkı sunulması durumunda satıcı veya sağlayıcı, tüketicilerin iletmiş olduğu cayma taleplerinin kendilerine ulaştığına ilişkin teyit bilgisini tüketiciye derhal iletmek zorundadır. (3) Sesli iletişim yoluyla yapılan satışlarda, satıcı veya sağlayıcı, EKte yer alan formu en geç mal teslimine veya hizmet ifasına kadar tüketiciye göndermek zorundadır. Tüketici bu tür satışlarda da cayma hakkını kullanmak için bu formu kullanabileceği gibi, ikinci fıkradaki yöntemleri de kullanabilir. (4) Bu maddede geçen cayma hakkının kullanımına ilişkin ispat yükümlülüğü tüketiciye aittir. (5)(Ek:RG-23/8/2022-31932)(1)Platform üzerinden kurulan mesafeli sözleşmelerde aracı hizmet sağlayıcı tüketicinin EKte yer alan formu doldurabilmesi veya cayma beyanını gönderebilmesi için platform üzerinde gerekli sistemi kurmak ve tüketicilerin iletmiş olduğu cayma beyanlarının kendisine ve satıcı veya sağlayıcıya ulaştığına ilişkin teyit bilgisini tüketiciye derhal iletmek zorundadır. Satıcı veya sağlayıcının yükümlülükleri'),
                array('Madde 12 – (değişik', 'RG-23/8/2022-31932)(2) (1) Satıcı, cayma hakkına konu malın, iade için ön bilgilendirmede belirtilen taşıyıcıya teslim edildiği tarihten itibaren on dört gün içinde, varsa malın tüketiciye teslim masrafları da dahil olmak üzere tahsil edilen tüm ödemeleri iade etmekle yükümlüdür. Ancak tüketicinin malı, iade için öngörülenin haricinde bir taşıyıcı ile iade etmesi durumunda söz konusu yükümlülük malın satıcıya ulaştığı tarihten itibaren başlar. Platform üzerinden kurulan ve bedelin tahsiline aracılık edilen mesafeli sözleşmelerde aracı hizmet sağlayıcı, teslim sonrası bedelin satıcıya aktarıldığı durum hariç olmak üzere bu fıkrada belirtilen ödemelerin tüketiciye iade edilmesinden satıcı ile birlikte müteselsilen sorumludur. (2) Malın tesliminden önce cayma hakkının kullanılması durumunda satıcı ile platform üzerinden kurulan ve bedelin tahsiline aracılık edilen mesafeli sözleşmelerde aracı hizmet sağlayıcı, cayma hakkının kullanıldığına ilişkin bildirimin kendisine ulaştığı tarihten itibaren on dört gün içinde, varsa malın tüketiciye teslim masrafları da dahil olmak üzere tahsil edilen tüm ödemeleri iade etmekle yükümlüdür. (3) Hizmet ifasına ilişkin sözleşmelerde cayma hakkının kullanılması durumunda sağlayıcı ile platform üzerinden kurulan ve bedelin tahsiline aracılık edilen mesafeli sözleşmelerde aracı hizmet sağlayıcı, cayma hakkının kullanıldığına ilişkin bildirimin kendisine ulaştığı tarihten itibaren on dört gün içinde tahsil edilen tüm ödemeleri iade etmekle yükümlüdür. (4) Satıcı veya sağlayıcı, birinci, ikinci ve üçüncü fıkralarda belirtilen tüm geri ödemeleri,(Mülga ibare:RG-24/5/2025-32909)(4)tüketicinin satın alırken kullandığı ödeme aracına uygun bir şekilde ve tüketiciye herhangi bir masraf veya yükümlülük getirmeden tek seferde yapmak zorundadır. Platform üzerinden kurulan mesafeli sözleşmelerde satıcı veya sağlayıcı adına bedel tahsil etmesi halinde, mal veya hizmetin tüketiciye teslim veya ifası sonrası bedelin satıcıya veya sağlayıcıya aktarıldığı durumlar hariç olmak üzere, aracı hizmet sağlayıcı bu yükümlülüğün yerine getirilmesinden satıcı veya sağlayıcı ile birlikte müteselsilen sorumludur. Ödemenin kredi kartı ile yapılmış olması durumunda, 23/2/2006 tarihli ve 5464 sayılı Banka Kartları ve Kredi Kartları Kanunu kapsamındaki kart çıkaran kuruluşlar; satıcı, sağlayıcı veya aracı hizmet sağlayıcı tarafından aktarılan tutarı, kendilerine ulaşmasını takiben kart hamilinin kullanılabilir limitine tek seferde ilave etmekle yükümlüdür. (5)(Değişik:RG-24/5/2025-32909)(4)Cayma hakkının kullanımında, 5 inci maddenin birinci fıkrasının (g) bendi kapsamında, satıcının iade için belirttiği taşıyıcı aracılığıyla malın geri gönderilmesi halinde, tüketici iadeye ilişkin masraflardan sorumlu tutulamaz. Satıcının ön bilgilendirmede iade için herhangi bir taşıyıcıyı belirtmediği durumda ise tüketiciden iade masrafına ilişkin herhangi bir bedel talep edilemez. İade için ön bilgilendirmede belirtilen taşıyıcının, tüketicinin bulunduğu yerde şubesinin olmaması durumunda satıcı, ilave hiçbir masraf talep etmeksizin iade edilmek istenen malın tüketiciden alınmasını sağlamakla yükümlüdür. Platform üzerinden kurulan mesafeli sözleşmelerde ise iade için öngörülen taşıyıcıya ilişkin bilgiye ön bilgilendirmede yer verilmemesi ya da belirtilen taşıyıcının tüketicinin bulunduğu yerde şubesinin olmaması aracı hizmet sağlayıcıdan kaynaklanıyorsa söz konusu masraf ve yükümlülükler aracı hizmet sağlayıcı tarafından karşılanmak zorundadır. (6) Platform üzerinden kurulan mesafeli sözleşmelerde, satıcı veya sağlayıcı, tüketicinin cayma hakkını kullandığına ilişkin kendisine ulaşan bildirimi aracı hizmet sağlayıcıya derhal ulaştırmakla yükümlüdür. Aracı hizmet sağlayıcının yükümlülükleri'),
                array('Madde 12/a – (ek', 'RG-23/8/2022-31932)(1) (1) Aracı hizmet sağlayıcı, platform üzerinden kurulan mesafeli sözleşmelerden doğan hak ve yükümlülüklerin kullanım süresi boyunca tüketicilerin aşağıda belirtilen hususlara ilişkin talep ve bildirimlerini iletebilmelerine ve takip edebilmelerine elverişli bir sistemi kurmak, kesintisiz olarak açık tutmak zorundadır: 37. a) Cayma hakkının kullanıldığına dair bildirim. 38. b) Sözleşmenin feshine dair bildirim. 39. c) Bedel iadesi talebi. ç) Tüketicilerin satıcı veya sağlayıcı ile yaptıkları işlemlere ilişkin kayıtların talebi. 40. d) Teslimat veya ifaya ilişkin talep ve şikayetler. (2) Aracı hizmet sağlayıcı, birinci fıkrada belirtilen talep ve bildirimleri, satıcı veya sağlayıcıya derhal iletmek zorundadır. (3) Aracı hizmet sağlayıcı, ön bilgilendirmenin yapılması, teyidi ve ön bilgilendirmenin yapıldığının ispatından satıcı veya sağlayıcı ile birlikte müteselsilen sorumludur. (4) Veri girişinin aracı hizmet sağlayıcı tarafından yapıldığı durumlarda, 5 inci maddede belirlenen ön bilgilendirmede bulunulması zorunlu hususlardaki eksikliklerden aracı hizmet sağlayıcı sorumludur. (5) Aracı hizmet sağlayıcı, bu Yönetmelikte yer alan hususlardan dolayı tüketicinin satıcı veya sağlayıcılar ile yaptıkları işlemlere ilişkin kayıtların üç yıl boyunca tutulmasından ve istenilmesi halinde bu bilgilerin ilgili kurum ve kuruluşlar ile tüketicilere verilmesinden sorumludur. (6) Aracı hizmet sağlayıcı, satıcı veya sağlayıcı ile yaptığı aracılık hizmetine ilişkin sözleşmeye aykırı uygulamaları nedeniyle satıcı ve sağlayıcının Kanunun 48 inci maddesine ve bu Yönetmelik hükümlerine aykırı davranmasına sebep olduğu her bir tüketici işleminden sorumludur. (7) Satıcı veya sağlayıcı adına bedel tahsil etmesi halinde aracı hizmet sağlayıcı; 41. a) Malın teslimi veya hizmetin ifasından önce tüketicinin cayma hakkını kullanması durumunda cayma hakkının kullanıldığına ilişkin bildirimin kendisine ulaştığı tarihten itibaren, 42. b) Malın tesliminden sonra tüketicinin cayma hakkını kullanması durumunda, cayma bildiriminin kendisine ulaştığı tarih itibarıyla bedel satıcıya aktarılmamışsa cayma hakkına konu malın, iade için öngörülen taşıyıcıya teslim edildiği tarihten veya iade için öngörülenin haricinde bir taşıyıcı ile iade edilmesi durumunda da satıcıya ulaştığı tarihten itibaren,(2) 43. c) Tüketicinin 16 ncı maddede belirtilen sözleşmeyi fesih hakkını kullanması durumunda fesih bildiriminin kendisine ulaştığı tarihten itibaren, on dört gün içinde, tahsil ettiği mal veya hizmet bedeli ile teslimat masraflarının tüketiciye iadesinden, satıcı veya sağlayıcı ile birlikte müteselsilen sorumludur. (8) Aracı hizmet sağlayıcı, satıcı veya sağlayıcının onayı olmaksızın düzenlediği kampanyalı, promosyonlu veya indirimli satışlara ilişkin olarak aracılık ettiği mesafeli sözleşmelerde kampanya ve benzeri taahhütlerin karşılanmamasının neden olduğu sözleşmenin hiç ya da gereği gibi ifa edilmemesi hallerinden sorumludur. (9) Satışa sunulan mal veya hizmete ilişkin platform üzerinden yapılan reklam ve tanıtımlarda taahhüt edilen bilgiler ile ön bilgilendirmede bulunması zorunlu hususların uyumlu olmasından ve ispatından aracı hizmet sağlayıcı sorumludur. Tüketicinin yükümlülükleri'),
                array('Madde 13 – (1) Satıcı Veya Sağlayıcı Malı Kendisinin Geri Alacağına Dair Bir Teklifte Bulunmadıkça, Tüketici Cayma Hakkını Kullandığına İlişkin Bildirimi Yönelttiği Tarihten İtibaren On(ek İbare', 'RG-23/8/2022-31932)(2)dörtgün içinde malı satıcı veya sağlayıcıya ya da yetkilendirmiş olduğu kişiye geri göndermek zorundadır. (2) Tüketici, cayma süresi içinde malı, işleyişine, teknik özelliklerine ve kullanım talimatlarına uygun bir şekilde kullandığı takdirde meydana gelen değişiklik ve bozulmalardan sorumlu değildir. (3)(Ek:RG-23/8/2022-31932)(2)(Mülga:RG-24/5/2025-32909)(4) Cayma hakkının kullanımının yan sözleşmelere etkisi'),
                array('Madde 14 (1) Kanunun 30 uncu maddesi hükümleri saklı kalmak koşuluyla, tüketicinin cayma hakkını kullanması durumunda yan sözleşmeler de kendiliğinden sona erer. Bu durumda tüketici, 13 üncü maddenin ikinci fıkrasında belirtilen haller dışında herhangi bir masraf, tazminat veya cezai şart ödemekle yükümlü değildir.', '(2) Satıcı veya sağlayıcı, tüketicinin cayma hakkını kullandığını yan sözleşmenin tarafı olan üçüncü kişiye derhal bildirmelidir.(Ek cümle:RG-23/8/2022-31932)(1)Platform üzerinden kurulan mesafeli sözleşmelerde yan sözleşmeye aracılık edilmesi halinde bu bildirimin yapılmasından aracı hizmet sağlayıcı da sorumludur. Cayma hakkının istisnaları'),
                array('Madde 15 – (1) Taraflarca Aksi Kararlaştırılmadıkça, Tüketici Aşağıdaki Sözleşmelerde Cayma Hakkını Kullanamaz', '44. a) Fiyatı finansal piyasalardaki dalgalanmalara bağlı olarak değişen ve satıcı veya sağlayıcının kontrolünde olmayan mal veya hizmetlere ilişkin sözleşmeler. 45. b) Tüketicinin istekleri veya kişisel ihtiyaçları doğrultusunda hazırlanan mallara ilişkin sözleşmeler. 46. c) Çabuk bozulabilen veya son kullanma tarihi geçebilecek malların teslimine ilişkin sözleşmeler. ç) Tesliminden sonra ambalaj, bant, mühür, paket gibi koruyucu unsurları açılmış olan mallardan; iadesi sağlık ve hijyen açısından uygun olmayanların teslimine ilişkin sözleşmeler. 47. d) Tesliminden sonra başka ürünlerle karışan ve doğası gereği ayrıştırılması mümkün olmayan mallara ilişkin sözleşmeler. 48. e) Malın tesliminden sonra ambalaj, bant, mühür, paket gibi koruyucu unsurları açılmış olması halinde maddi ortamda sunulan kitap, dijital içerik ve bilgisayar sarf malzemelerine ilişkin sözleşmeler. 49. f) Abonelik sözleşmesi kapsamında sağlananlar dışında, gazete ve dergi gibi süreli yayınların teslimine ilişkin sözleşmeler. 50. g) Belirli bir tarihte veya dönemde yapılması gereken, konaklama, eşya taşıma, araba kiralama, yiyecek-içecek tedariki ve eğlence veya dinlenme amacıyla yapılan boş zamanın değerlendirilmesine ilişkin sözleşmeler. ğ) Elektronik ortamda anında ifa edilen hizmetler veya tüketiciye anında teslim edilen gayrimaddi mallara ilişkin sözleşmeler. 51. h) Cayma hakkı süresi sona ermeden önce, tüketicinin onayı ile ifasına başlanan hizmetlere ilişkin sözleşmeler. ı)(Ek:RG-23/8/2022-31932)(2)(Danıştay Onuncu Dairesinin 30/6/2025 tarihli ve E.:2022/5534 sayılı kararı ile yürütmesi durdurulan bent:13/10/1983 tarihli ve 2918 sayılı Karayolları Trafik Kanununa göre tescili zorunlu olan taşınırlar ile kayıt veya tescil zorunluluğu bulunan insansız hava araçlarına ilişkin sözleşmeler.) 52. i)(Ek:RG-23/8/2022-31932)(2)(Mülga:RG-24/5/2025-32909)(4) 53. j)(Ek:RG-23/8/2022-31932)(2)Canlı müzayede şeklinde açık artırma yoluyla akdedilen sözleşmeler. 54. k)(Ek:RG-23/8/2022-31932)(2)(Danıştay Onuncu Dairesinin 30/6/2025 tarihli ve E.:2022/5534 sayılı kararı ile yürütmesi durdurulan bent:Tanıtma ve kullanma kılavuzunda satıcı veya yetkili servis tarafından kurulum veya montajının yapılacağı belirtilen mallardan kurulum ya da montajı yapılanlara ilişkin sözleşmeler.)'),
                array('Dördüncü Bölüm', 'Diğer Hükümler Sözleşmenin ifası ve teslimat'),
                array('Madde 16 – (1)(değişik', 'RG-23/8/2022-31932)(1)Satıcı veya sağlayıcı, tüketicinin siparişinin kendisine ulaştığı tarihten itibaren taahhüt ettiği süre içinde edimini yerine getirmek zorundadır. Tüketicinin isteği veya kişisel ihtiyaçları doğrultusunda hazırlanan mallara ilişkin sözleşmeler haricinde mal satışlarında bu süre her halükarda otuz günü geçemez. (2) Satıcı veya sağlayıcının birinci fıkrada yer alan yükümlülüğünü yerine getirmemesi durumunda, tüketici sözleşmeyi feshedebilir. (3) Sözleşmenin feshi durumunda, satıcı veya sağlayıcı, varsa teslimat masrafları da dâhil olmak üzere tahsil edilen tüm ödemeleri fesih bildiriminin kendisine ulaştığı tarihten itibaren on dört gün içinde tüketiciye 4/12/1984 tarihli ve 3095 sayılı Kanuni Faiz ve Temerrüt Faizine İlişkin Kanunun 1 inci maddesine göre belirlenen kanuni faiziyle birlikte geri ödemek ve varsa tüketiciyi borç altına sokan tüm kıymetli evrak ve benzeri belgeleri iade etmek zorundadır. (4)(Değişik:RG-23/8/2022-31932)(1)Sipariş konusu mal ya da hizmet ediminin yerine getirilmesinin imkansızlaştığı hallerde satıcı veya sağlayıcının ve satıcı veya sağlayıcı adına bedel tahsil etmesi halinde aracı hizmet sağlayıcının bu durumu öğrendiği tarihten itibaren üç gün içinde tüketiciye yazılı olarak veya kalıcı veri saklayıcısı ile bildirmesi ve varsa teslimat masrafları da dâhil olmak üzere tahsil edilen tüm ödemeleri bildirim tarihinden itibaren en geç on dört gün içinde iade etmesi zorunludur. Malın stokta bulunmaması durumu, mal ediminin yerine getirilmesinin imkânsızlaşması olarak kabul edilmez. Zarardan sorumluluk'),
                array('Madde 17 (1) Satıcı, malın tüketici ya da tüketicinin taşıyıcı dışında belirleyeceği üçüncü bir kişiye teslimine kadar oluşan kayıp ve hasarlardan sorumludur.', '(2) Tüketicinin, satıcının belirlediği taşıyıcı dışında başka bir taşıyıcı ile malın gönderilmesini talep etmesi durumunda, malın ilgili taşıyıcıya tesliminden itibaren oluşabilecek kayıp ya da hasardan satıcı sorumlu değildir. Telefon kullanım ücreti'),
                array('Madde 18 (1) Kurulmuş olan sözleşmeye ilişkin olarak tüketicilerin iletişime geçebilmesi için satıcı veya sağlayıcı tarafından bir telefon hattı tahsis edilmesi durumunda, bu hat ile ilgili olarak satıcı veya sağlayıcı olağan ücret tarifesinden daha yüksek bir tarife seçemez.', 'İlave ödemeler'),
                array('Madde 19 (1) Sözleşme kurulmadan önce, sözleşme yükümlülüğünden kaynaklanan ve üzerinde anlaşılmış esas bedel dışında herhangi bir ilave bedel talep edilebilmesi için tüketicinin açık onayının ayrıca alınması zorunludur.', '(2) Tüketicinin açık onayı alınmadan ilave ödeme yükümlülüğü doğuran seçeneklerin kendiliğinden seçili olarak sunulmuş olmasından dolayı tüketici bir ödemede bulunmuş ise, satıcı veya sağlayıcı(Ek ibare:RG-23/8/2022-31932)(1) ile platform üzerinden kurulan mesafeli sözleşmelerde satıcı veya sağlayıcı adına bedel tahsil etmesi halinde aracı hizmet sağlayıcıbu ödemelerin iadesini derhal yapmak zorundadır. Bilgilerin saklanması ve ispat yükümlülüğü'),
                array('Madde 20 −-(1) Satıcı veya sağlayıcı, bu Yönetmelik kapsamında düzenlenen cayma hakkı, bilgilendirme, teslimat ve diğer hususlardaki yükümlülüklerine dair her bir işleme ilişkin bilgi ve belgeyi üç yıl boyunca saklamak zorundadır.', '(2)(Değişik cümle:RG-23/8/2022-31932)(1)Aracı hizmet sağlayıcı, bu Yönetmelikte yer alan hususlardan dolayı satıcı veya sağlayıcı ile yapılan işlemlere ilişkin kayıtları üç yıl boyunca tutmak ve istenilmesi halinde bu bilgileri ilgili kurum, kuruluş ve tüketicilere vermekle yükümlüdür.(Ek cümle:RG-9/2/2019-30681)Ancak abonelik sözleşmesinin kamu hizmetlerinin tek noktadan sunulduğu ortak kamu elektronik platformu üzerinden kurulması halinde, kayıtların tutulması ve bilgilerin sunulmasına ilişkin yükümlülük satıcı veya sağlayıcıya aittir. (3) Satıcı veya sağlayıcı elektronik ortamda tüketiciye teslim edilen gayrimaddi malların veya ifa edilen hizmetlerin ayıpsız olduğunu ispatla yükümlüdür.'),
                array('Beşinci Bölüm', 'Çeşitli ve Son Hükümler Yürürlükten kaldırılan yönetmelik'),
                array('Madde 21 (1) 6/3/2011 tarihli ve 27866 sayılı Resmî Gazetede yayımlanan Mesafeli Sözleşmelere Dair Yönetmelik yürürlükten kaldırılmıştır.', 'Geçiş hükümleri GEÇİCİ MADDE 1-(Ek:RG-4/11/2023-32359)(3) (1) Bu Yönetmeliğin,23/8/2022tarihli ve 31932 sayılı Resmî Gazetede yayımlanan Mesafeli Sözleşmeler Yönetmeliğinde Değişiklik Yapılmasına Dair Yönetmelik ile değiştirilen; 55. a) 5 inci maddesinin birinci fıkrasının (g) bendi, 56. b) 12ncimaddesi, 57. c) 12/A maddesinin yedinci fıkrasının (b) bendi, ç) 13 üncü maddesinin birinci fıkrasında yer alan “dört” ibaresi ile üçüncü fıkrası, 58. d) 15 inci maddesinin birinci fıkrasının (ı), (i), (j) ve (k) bentleri, hükümleri(Değişik ibare:RG-10/8/2024-32628)1/1/2026tarihine kadar uygulanmaz. (2)(Değişik ibare:RG-10/8/2024-32628)1/1/2026tarihine kadar birinci fıkrada belirtilen hükümlerin, 23/8/2022 tarihli ve 31932 sayılı Resmî Gazetede yayımlanan Mesafeli Sözleşmeler Yönetmeliğinde Değişiklik Yapılmasına Dair Yönetmelik ile değiştirilmeden önce yürürlükte bulunan halleri uygulanmaya devam olunur. Yürürlük'),
                array('Madde 22 (1) Bu Yönetmelik yayımı tarihinden itibaren üç ay sonra yürürlüğe girer.', 'Yürütme'),
                array('Madde 23 – (1) Bu Yönetmelik Hükümlerini(değişik İbare', 'RG-23/8/2022-31932)(1) Ticaret Bakanıyürütür. _____________________ (1) Bu değişiklik 1/10/2022 tarihinde yürürlüğe girer. (2) 14/9/2022 tarihli ve 31953 sayılı Resmî Gazetede yayımlanan Yönetmelik uyarınca 23/8/2022 tarihli ve 31932 sayılı Resmî Gazetede yayımlanan değişiklikle Yönetmeliğin 5 inci maddesinin birinci fıkrasının (g) bendi, 12 nci maddesi, 12/A maddesinin yedinci fıkrasının (b) bendi, 13 üncü maddesinin birinci fıkrasına eklenen “dört” ibaresi ve aynı maddeye eklenen fıkra ile 15 inci maddesinin birinci fıkrasına eklenen bentler1/1/2024 tarihinde yürürlüğe girer. (3) Bu değişiklik 1/1/2024 tarihinde yürürlüğe girer. (4) Bu değişiklik 1/1/2026 tarihinde yürürlüğe girer. Yönetmeliğin Yayımlandığı Resmî Gazetenin Tarihi Sayısı 27/11/2014 29188 Yönetmelikte Değişiklik Yapan Yönetmeliklerin Yayımlandığı Resmî Gazetelerin Tarihi Sayısı 1. 9/2/2019 30681 2. 23/8/2022 31932 3. 4/11/2023 32359 4. 10/8/2024 32628 5. 24/5/2025 32909 EK'),
                array('Örnek Cayma Formu', '(Bu form, sadece sözleşmeden cayma hakkı kullanılmak istenildiğinde doldurup gönderilecektir.) -Kime:(Satıcı veya sağlayıcı tarafından doldurulacak olan bu kısımda satıcı veya sağlayıcının ismi, unvanı, adresi varsa faks numarası ve e-posta adresi yer alacaktır.) -Bu formla aşağıdaki malların satışına veya hizmetlerin sunulmasına ilişkin sözleşmeden cayma hakkımı kullandığımı beyan ederim. -Sipariş tarihi veya teslim tarihi: -Cayma hakkına konu mal veya hizmet: -Cayma hakkına konu mal veya hizmetin bedeli: -Tüketicinin adı ve soyadı: -Tüketicinin adresi: -Tüketicinin imzası:(Sadece kağıt üzerinde gönderilmesi halinde) -Tarih:'),
            ),
