/* ──────────────────────────────────────────────
   Sayfaları otomatik oluştur (tema etkinleşince)
────────────────────────────────────────────── */
function pazaryeri_create_help_pages() {
    $pages = pazaryeri_help_pages_data();
    foreach ( $pages as $slug => $data ) {
        if ( ! get_page_by_path( $slug ) ) {
            wp_insert_post( array(
                'post_title'   => $data['title'],
                'post_name'    => $slug,
                'post_content' => '[pazaryeri_help slug="' . $slug . '"]',
                'post_status'  => 'publish',
                'post_type'    => 'page',
            ) );
        }
    }
}

/* ──────────────────────────────────────────────
   Shortcode: [pazaryeri_help slug="..."]
────────────────────────────────────────────── */
add_shortcode( 'pazaryeri_help', function ( $atts ) {
    $atts = shortcode_atts( array( 'slug' => '' ), $atts );
    $pages = pazaryeri_help_pages_data();
    $slug  = $atts['slug'];
    if ( ! isset( $pages[ $slug ] ) ) return '';
    $p = $pages[ $slug ];

    ob_start(); ?>
    <div class="help-page">
      <div class="help-hero">
        <div class="help-hero-icon"><?php echo $p['icon']; ?></div>
        <h1 class="help-hero-title"><?php echo esc_html( $p['title'] ); ?></h1>
        <p class="help-hero-intro"><?php echo esc_html( $p['intro'] ); ?></p>
      </div>

      <?php if ( ! empty( $p['steps'] ) ) : ?>
        <div class="help-steps">
          <?php foreach ( $p['steps'] as $s ) : ?>
            <div class="help-step">
              <div class="help-step-num"><?php echo esc_html( $s[0] ); ?></div>
              <div class="help-step-body">
                <div class="help-step-title"><?php echo esc_html( $s[1] ); ?></div>
                <div class="help-step-desc"><?php echo esc_html( $s[2] ); ?></div>
              </div>
            </div>
          <?php endforeach; ?>
        </div>
      <?php endif; ?>

      <?php if ( ! empty( $p['cards'] ) ) : ?>
        <div class="help-cards">
          <?php foreach ( $p['cards'] as $c ) : ?>
            <div class="help-card">
              <div class="help-card-icon"><?php echo $c[0]; ?></div>
              <div class="help-card-title"><?php echo esc_html( $c[1] ); ?></div>
              <div class="help-card-desc"><?php echo esc_html( $c[2] ); ?></div>
            </div>
          <?php endforeach; ?>
        </div>
      <?php endif; ?>

      <?php if ( ! empty( $p['table'] ) ) : ?>
        <div class="help-table-wrap">
          <table class="help-table">
            <thead><tr><?php foreach ( $p['table']['head'] as $h ) : ?><th><?php echo esc_html( $h ); ?></th><?php endforeach; ?></tr></thead>
            <tbody>
              <?php foreach ( $p['table']['rows'] as $row ) : ?>
                <tr><?php foreach ( $row as $cell ) : ?><td><?php echo esc_html( $cell ); ?></td><?php endforeach; ?></tr>
              <?php endforeach; ?>
            </tbody>
          </table>
        </div>
      <?php endif; ?>

      <?php if ( ! empty( $p['links_grid'] ) ) : ?>
        <div class="help-links-grid">
          <?php foreach ( $p['links_grid'] as $l ) : ?>
            <a class="help-link-card" href="<?php echo esc_url( home_url( $l[3] ) ); ?>">
              <div class="help-link-icon"><?php echo $l[0]; ?></div>
              <div class="help-link-title"><?php echo esc_html( $l[1] ); ?></div>
              <div class="help-link-desc"><?php echo esc_html( $l[2] ); ?></div>
            </a>
          <?php endforeach; ?>
        </div>
      <?php endif; ?>

      <?php if ( ! empty( $p['sections'] ) ) : ?>
        <div class="help-sections">
          <?php foreach ( $p['sections'] as $sec ) : ?>
            <div class="help-section">
              <h2 class="help-section-title"><?php echo esc_html( $sec[0] ); ?></h2>
              <p class="help-section-text"><?php echo esc_html( $sec[1] ); ?></p>
            </div>
          <?php endforeach; ?>
        </div>
      <?php endif; ?>

      <?php if ( ! empty( $p['faq'] ) ) : ?>
        <div class="help-faq">
          <h2 class="help-faq-head">Sıkça Sorulan Sorular</h2>
          <?php foreach ( $p['faq'] as $f ) : ?>
            <div class="help-faq-item">
              <div class="help-faq-q" onclick="this.parentNode.classList.toggle('open')"><?php echo esc_html( $f[0] ); ?> <span>+</span></div>
              <div class="help-faq-a"><?php echo esc_html( $f[1] ); ?></div>
            </div>
          <?php endforeach; ?>
        </div>
      <?php endif; ?>

      <!-- Yardım CTA -->
      <div class="help-cta">
        <div class="help-cta-text">
          <div class="help-cta-title">Sorunuz mu var?</div>
          <div class="help-cta-sub">Aradığınızı bulamadıysanız destek ekibimiz size yardımcı olmaktan mutluluk duyar.</div>
        </div>
        <a class="help-cta-btn" href="<?php echo esc_url( home_url( '/iletisim/' ) ); ?>">Bize Ulaşın →</a>
      </div>
    </div>
    <?php
    return ob_get_clean();
} );
